// Official German StVO traffic-sign graphics for the extended lane-status sign codes,
// embedded as data-URIs. Each is the canonical Wikimedia Commons SVG, verified PUBLIC DOMAIN
// (source: https://wiki.openstreetmap.org/wiki/DE:Verkehrszeichen_in_Deutschland):
//   cyclePath            -> Zeichen 237 Radweg  (PD-VzKat, PD-GermanGov)
//   cyclePathClosed      -> Zeichen 254 Verbot für Radverkehr  (PD-VzKat, PD-GermanGov)
//   footPath             -> Zeichen 239 Gehweg  (PD-VzKat, PD-GermanGov)
//   footPathClosed       -> Zeichen 259 Verbot für Fußgänger  (PD-GermanGov)
//   parking              -> Zeichen 314 Parken  (PD-VzKat, PD-GermanGov)
//   noStoppingRestricted -> Zeichen 286 Eingeschränktes Haltverbot  (PD-Vz historisch, PD-GermanGov)
//   noStoppingAbsolute   -> Zeichen 283 Absolutes Haltverbot  (PD-VzKat, PD-GermanGov)

import type { LaneStatusSymbol } from './laneStatusCoded'

/** data:image/svg+xml data-URIs, keyed by the sign symbol. Rendered via an SVG <image>. */
export const LANE_STATUS_SIGNS: Partial<Record<LaneStatusSymbol, string>> = {
  cyclePath:
    'data:image/svg+xml;base64,',
  cyclePathClosed:
    'data:image/svg+xml;base64,',
  footPath:
    'data:image/svg+xml;base64,',
  footPathClosed:
    'data:image/svg+xml;base64,',
  parking:
    'data:image/svg+xml;base64,',
  noStoppingRestricted:
    'data:image/svg+xml;base64,',
  noStoppingAbsolute:
    'data:image/svg+xml;base64,',
}
